// 右上角齿轮：切到「我的」。
onMine() {
  this.triggerEvent('mine');
},

// 「完成」：退出排序模式。
onToggle() {
  this.triggerEvent('toggle');
},

// 「在此象限新建」：带默认象限进新建抽屉。
onNewHere() {
  this.triggerEvent('new-here');
},

// 把被点那一个的 dataset 原样交给页面。
// 交给页面的形状与原生事件一致（currentTarget.dataset），
// 所以页面上的 onTab 只换取值来源、不必为「事件来自组件」写第二套分支。
onPick(e) {
  this.triggerEvent('pick', e.currentTarget.dataset);
},
